PREFIX orkgp: <http://orkg.org/orkg/predicate/>
PREFIX orkgc: <http://orkg.org/orkg/class/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?paper ?paperLabel ?objective ?objectiveLabel WHERE {
  ?paper orkgp:P31 ?contribution .
  ?contribution a orkgc:C112000 .
  ?paper rdfs:label ?paperLabel .
  { ?contribution orkgp:P67098 ?objective } UNION { ?contribution orkgp:P107003 ?objective }
  OPTIONAL { ?objective rdfs:label ?objectiveLabel }
} ORDER BY ?paperLabel

